func inLower(cp int32) int32 {
	if (cp >= 65) && (cp <= 90) {
		return cp + 32
	}
	return cp
}

func InLang(loc *port.Cells) int32 {
	// The language of a locale tag held as code points (`en`, `en-US`, `DE_ch`): LG_NONE for no tag, else an LG_
	// code, LG_OTHER for a language without a table.
	var n int32 = port.CellsLen(loc)
	if n < 2 {
		return lgNone
	}
	var a int32 = inLower(port.CellsAt(loc, 0))
	var b int32 = inLower(port.CellsAt(loc, 1))
	var c int32 = 45
	if n > 2 {
		c = port.CellsAt(loc, 2)
	}
	if (c != 45) && (c != 95) {
		return lgOther
	}
	if (a == 101) && (b == 110) {
		return lgEn
	}
	if (a == 100) && (b == 101) {
		return lgDe
	}
	if (a == 102) && (b == 114) {
		return lgFr
	}
	if (a == 101) && (b == 115) {
		return lgEs
	}
	if (a == 112) && (b == 116) {
		return lgPt
	}
	if (a == 105) && (b == 116) {
		return lgIt
	}
	if (a == 110) && (b == 108) {
		return lgNl
	}
	return lgOther
}

func inOneLetter(lang int32, cp int32) bool {
	// Is the upper-case code point cp a word of its own in language `lang` (the union of the tables when LG_NONE or
	// LG_OTHER)?
	var i int32 = 0
	var cur int32 = -1
	for i < 38 {
		var v int32 = InOne[i]
		if cur < 0 {
			cur = v
		} else if v == 0 {
			cur = -1
		} else if (v == cp) && ((cur == lang) || ((lang == lgNone) || (lang == lgOther))) {
			return 1 == 1
		}
		i += 1
	}
	return 0 == 1
}

func inFollows(lang int32, kind int32, letter int32, et *port.Cells, ts int32, tl int32) bool {
	// Is the word et[ts, ts+tl) (lower-cased) in the list `kind` (1 the words a one-letter word is followed by, 2 the
	// rest of a word the letter begins) for (lang, letter)?
	var n int32 = 685
	var i int32 = 0
	var inlang int32 = 0
	var inlet int32 = 0
	var w int32 = 0
	var k int32 = 0
	var same int32 = 0
	for i < n {
		var v int32 = InFollow[i]
		if inlang == 0 {
			if v == 0 {
				return 0 == 1
			}
			inlang = v
			inlet = 0
			i += 1
		} else if inlet == 0 {
			if v == 0 {
				inlang = 0
				i += 1
			} else {
				inlet = v
				i += 1
			}
		} else {
			if v == 0 {
				inlet = 0
				i += 1
			} else {
				w = v
				if (inlang == ((lang * 10) + kind)) && (inlet == letter) && (w == tl) {
					same = 1
					k = 0
					for k < w {
						if InFollow[i+(1+k)] != inLower(port.CellsAt(et, ts+k)) {
							same = 0
						}
						k += 1
					}
					if same == 1 {
						return 1 == 1
					}
				}
				i += 1 + w
			}
		}
	}
	return 0 == 1
}

func InJoin(loc *port.Cells, cp int32, et *port.Cells, ts int32, tl int32) int32 {
	// How an initial whose whole text is the code point cp (upper case or not) meets the first word of its first
	// line, et[ts, ts+tl) (an empty word is tl 0): 0 joined and sure, 1 joined and flagged low-conf, 2 a space.
	var lang int32 = InLang(loc)
	var up int32 = cp
	if (cp >= 97) && (cp <= 122) {
		up = cp - 32
	}
	if !inOneLetter(lang, up) {
		return 0
	}
	if (lang == lgEn) && (tl > 0) {
		if inFollows(lang, 1, up, et, ts, tl) {
			return 2
		}
		if inFollows(lang, 2, up, et, ts, tl) {
			return 0
		}
	}
	return 1
}

func inJoinOf(wd *port.Cells, et *port.Cells, lt *port.Cells, loc *port.Cells, ii *port.Cells, r int32) int32 {
	// How the initial of row r of `ii` meets the first word of its first line: 0 joined and sure, 1 joined and
	// flagged low-conf, 2 a space. One code point: `in-join`'s table and lists. Two or more that begin with a letter or
	// digit: a whole first word (`IT`), a space, unless it is of a script written without spaces; one that begins with
	// punctuation (`“N`) is joined. A raised initial is part of its word.
	var rr int32 = r * iiStride
	var il int32 = port.CellsAt(ii, rr+iiIl)
	var ncp int32 = port.CellsAt(ii, rr+iiNcp)
	var iw int32 = port.CellsAt(ii, rr+iiWord)
	var w1 int32 = evidence.LnGet(lt, port.CellsAt(ii, rr+iiTl), evidence.LhFirst())
	if (il < 0) && (ncp < evidence.WdGet(wd, iw, evidence.HdTlen())) {
		return 0
	}
	var c0 int32 = inFirstCp(wd, et, iw)
	if c0 < 0 {
		return 0
	}
	if ncp == 1 {
		return InJoin(loc, c0, et, evidence.WdGet(wd, w1, evidence.HdTstart()), evidence.WdGet(wd, w1, evidence.HdTlen()))
	}
	if !inAlnum(c0) {
		return 0
	}
	if inIdeo(c0) {
		return 0
	}
	return 2
}

func InDetect(wd *port.Cells, gl *port.Cells, fo *port.Cells, et *port.Cells, npages int32, loc *port.Cells, lt *port.Cells, sc *port.Cells, sq *port.Cells, tm *port.Cells, ii *port.Cells) int32 {
	// Every page's initials. `lt` is the lines' copy (`lc-copy`): rewritten as the header says. `ii` is the table
	// of initials (stride 12); `loc` the locale tag as code points (empty for none), which decides the join. `sc sq tm`
	// are scratch. Answers the initials found.
	var nl int32 = port.CellsLen(lt) / 16
	var p int32 = 1
	var r int32 = 0
	var q int32 = 0
	port.CellsDrop(ii, 0)
	// Cell 15 is this stage's alone: whatever a producer left there is cleared.
	for r < nl {
		port.CellsSet(lt, (r*16)+15, 0)
		r += 1
	}
	for p <= npages {
		inPage(wd, gl, fo, et, lt, p, sc, sq, tm, ii)
		p += 1
	}
	q = port.CellsLen(ii) / iiStride
	r = 0
	for r < q {
		var rr int32 = r * iiStride
		var t int32 = port.CellsAt(ii, rr+iiTl)
		var jn int32 = inJoinOf(wd, et, lt, loc, ii, r)
		port.CellsSet(ii, rr+iiJoin, jn)
		if (t >= 0) && (t < nl) {
			var v int32 = (r + 1) * 4
			if port.CellsAt(ii, rr+iiIl) < 0 {
				v += 1
				if (port.CellsAt(ii, rr+iiNcp) == evidence.WdGet(wd, port.CellsAt(ii, rr+iiWord), evidence.HdTlen())) && (jn != 2) {
					v += 2
				}
			}
			port.CellsSet(lt, (t*16)+15, v)
		}
		r += 1
	}
	return q
}

func InGetIi(ii *port.Cells, r int32, f int32) int32 {
	return port.CellsAt(ii, (r*iiStride)+f)
}

func InRow(lt *port.Cells, l int32) int32 {
	// The row of `ii` whose target is row l of `lt`, -1 for none.
	if (l < 0) || (((l + 1) * 16) > port.CellsLen(lt)) {
		return -1
	}
	var c int32 = port.CellsAt(lt, (l*16)+15)
	if c < 4 {
		return -1
	}
	return (c / 4) - 1
}
